function useMFA() {
  const [isLoading, setIsLoading] = useState(true);
  const [currentLevel, setCurrentLevel] = useState(null);
  const [nextLevel, setNextLevel] = useState(null);
  const [hasMFAEnabled, setHasMFAEnabled] = useState(false);
  const checkMFAStatus = useCallback(async () => {
    setIsLoading(true);
    try {
      const { data: aalData, error: aalError } = await supabase.auth.mfa.getAuthenticatorAssuranceLevel();
      if (aalError) {
        console.error("Error checking AAL:", aalError);
        return;
      }
      setCurrentLevel(aalData.currentLevel);
      setNextLevel(aalData.nextLevel);
      const { data: factorsData, error: factorsError } = await supabase.auth.mfa.listFactors();
      if (factorsError) {
        console.error("Error listing factors:", factorsError);
        return;
      }
      const hasVerifiedTOTP = factorsData.totp.some((f) => f.status === "verified");
      setHasMFAEnabled(hasVerifiedTOTP);
    } catch (err) {
      console.error("MFA status check failed:", err);
    } finally {
      setIsLoading(false);
    }
  }, []);
  useEffect(() => {
    checkMFAStatus();
    const { data: { subscription } } = supabase.auth.onAuthStateChange(() => {
      checkMFAStatus();
    });
    return () => subscription.unsubscribe();
  }, [checkMFAStatus]);
  const needsMFAVerification = hasMFAEnabled && currentLevel === "aal1" && nextLevel === "aal2";
  return {
    isLoading,
    currentLevel,
    nextLevel,
    hasMFAEnabled,
    needsMFAVerification,
    refreshMFAStatus: checkMFAStatus
  };
}
