function normalizePhoneForStorage(phone) {
  let normalized = phone.replace(/[^\d+]/g, "");
  if (normalized.startsWith("0")) {
    normalized = "+972" + normalized.substring(1);
  } else if (normalized.startsWith("972") && !normalized.startsWith("+")) {
    normalized = "+" + normalized;
  } else if (!normalized.startsWith("+") && normalized.length > 0) {
    normalized = "+972" + normalized;
  }
  return normalized;
}
function usePatients(clinicId) {
  return useQuery({
    queryKey: ["patients", clinicId],
    queryFn: async () => {
      const { data: staffRoles } = await supabase.from("user_roles").select("user_id").in("role", ["admin", "doctor", "secretary"]);
      const staffUserIds = (staffRoles == null ? void 0 : staffRoles.map((r) => r.user_id).filter(Boolean)) || [];
      let query = supabase.from("patients").select("*, clinic:clinics(id, name)").order("created_at", { ascending: false });
      if (clinicId) {
        query = query.eq("clinic_id", clinicId);
      }
      const { data, error } = await query;
      if (error) throw error;
      const filteredData = (data || []).filter((patient) => {
        if (patient.status === "inactive") return false;
        return !patient.user_id || !staffUserIds.includes(patient.user_id);
      });
      return filteredData;
    }
  });
}
