function useAuditLog(filters = {}) {
  return useQuery({
    queryKey: ["audit-log", filters],
    queryFn: async () => {
      let query = supabase.from("audit_log").select("*").order("created_at", { ascending: false }).limit(500);
      if (filters.tableName) {
        query = query.eq("table_name", filters.tableName);
      }
      if (filters.action) {
        query = query.eq("action", filters.action);
      }
      if (filters.userId) {
        query = query.eq("user_id", filters.userId);
      }
      if (filters.startDate) {
        query = query.gte("created_at", filters.startDate);
      }
      if (filters.endDate) {
        query = query.lte("created_at", filters.endDate);
      }
      const { data, error } = await query;
      if (error) throw error;
      return data;
    }
  });
}
function useAuditLogTables() {
  return useQuery({
    queryKey: ["audit-log-tables"],
    queryFn: async () => {
      const { data, error } = await supabase.from("audit_log").select("table_name").not("table_name", "is", null);
      if (error) throw error;
      const uniqueTables = [...new Set(data.map((d) => d.table_name))].filter(Boolean);
      return uniqueTables.sort();
    }
  });
}
